package com.smartfitagent.db;
import com.smartfitagent.model.*; import java.nio.file.*; import java.util.*;
public class FileDatabase implements Database {
 private final Path dir; private UserProfile user; private final List<Course> courses=new ArrayList<>(); private final List<StudyPlan> plans=new ArrayList<>(); private final List<Note> notes=new ArrayList<>(); private final List<QuizQuestion> questions=new ArrayList<>(); private final List<QuizAttempt> attempts=new ArrayList<>();
 public FileDatabase(Path dir){this.dir=dir;} public FileDatabase(){this(Path.of("data"));} public void init() throws Exception{Files.createDirectories(dir);} public String name(){return "file:"+dir;} public Optional<UserProfile> user(){return Optional.ofNullable(user);} public void saveUser(UserProfile u){user=u;}
 public List<Course> courses(){return List.copyOf(courses);} public void saveCourse(Course c){courses.removeIf(x->x.id().equals(c.id()));courses.add(c);} public List<StudyPlan> plans(){return List.copyOf(plans);} public void savePlan(StudyPlan p){plans.removeIf(x->x.id().equals(p.id()));plans.add(p);} public List<Note> notes(){return List.copyOf(notes);} public void saveNote(Note n){notes.removeIf(x->x.id().equals(n.id()));notes.add(n);} public List<QuizQuestion> questions(){return List.copyOf(questions);} public void saveQuestion(QuizQuestion q){questions.removeIf(x->x.id().equals(q.id()));questions.add(q);} public List<QuizAttempt> attempts(){return List.copyOf(attempts);} public void saveAttempt(QuizAttempt a){attempts.removeIf(x->x.id().equals(a.id()));attempts.add(a);} }
